61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
68	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
69	     */
70	    /**
71	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
72	     * they can be routed and asserted independently of the application's diagnostic logging.
73	     */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /**
80	     * Common address abbreviations expanded to their full form during address normalization.
81	     * Matching is performed per whitespace-separated token on the upper-cased value.
82	     */
83	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
84	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper) {
98	        this.clinicService = clinicService;
99	        this.ownerMapper = ownerMapper;
100	        this.petMapper = petMapper;
101	        this.visitMapper = visitMapper;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        Owner owner = this.clinicService.findOwnerById(ownerId);
123	        if (owner == null) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
132	        HttpHeaders headers = new HttpHeaders();
133	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
134	        LocalDate effectiveDate = owner.getRegistrationDate() != null
135	            ? owner.getRegistrationDate() : LocalDate.now();
136	        LocalDate registrationDate = toBusinessDay(effectiveDate);
137	        owner.setRegistrationDate(registrationDate);
138	        long createdToday = this.clinicService.findAllOwners().stream()
139	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
140	            .count();
141	        if (createdToday >= 100) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        String address = normalizeAddress(owner.getAddress());
145	        if (address == null || address.isEmpty()) {
146	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
147	        }
148	        owner.setAddress(address);
149	        String telephone = toE164(owner.getTelephone());
150	        if (telephone == null) {
151	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
152	        }
153	        owner.setTelephone(telephone);
154	        if (owner.getEmail() != null) {
155	            String email = normalizeEmail(owner.getEmail());
156	            if (!EMAIL_PATTERN.matcher(email).matches()) {
157	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	            }
159	            owner.setEmail(email);
160	        }
161	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
162	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
163	        if (telephoneInUse) {
164	            return new ResponseEntity<>(HttpStatus.CONFLICT);
165	        }
166	        String cityKey = householdKey(owner.getCity());
167	        long cityCount = this.clinicService.findAllOwners().stream()
168	            .filter(existing -> existing.getCity() != null
169	                && cityKey.equals(householdKey(existing.getCity())))
170	            .count();
171	        if (cityCount >= 50) {
172	            return new ResponseEntity<>(HttpStatus.CONFLICT);
173	        }
174	        String lastNameKey = householdKey(owner.getLastName());
175	        String addressKey = householdKey(owner.getAddress());
176	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
177	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
178	                && addressKey.equals(householdKey(existing.getAddress())))
179	            .toList();
180	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
181	            String householdId = householdMembers.stream()
182	                .map(Owner::getHouseholdId)
183	                .filter(Objects::nonNull)
184	                .findFirst()
185	                .orElseGet(() -> householdId(owner));
186	            owner.setHouseholdId(householdId);
187	            for (Owner member : householdMembers) {
188	                if (member.getHouseholdId() == null) {
189	                    member.setHouseholdId(householdId);
190	                    this.clinicService.saveOwner(member);
191	                }
192	            }
193	        } else if (!householdMembers.isEmpty()) {
194	            return new ResponseEntity<>(HttpStatus.CONFLICT);
195	        }
196	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
197	        String firstNameKey = householdKey(owner.getFirstName());
198	        String namesakeLastNameKey = householdKey(owner.getLastName());
199	        long namesakeCount = this.clinicService.findAllOwners().stream()
200	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
201	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
202	            .count();
203	        owner.setNamesakeCount((int) namesakeCount);
204	        this.clinicService.saveOwner(owner);
205	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
206	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
207	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
208	        headers.setLocation(UriComponentsBuilder.newInstance()
209	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
210	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
211	    }
212	
213	    /**
214	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
215	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
216	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
217	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
218	     *
219	     * @param telephone the raw telephone value (may be {@code null})
220	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
221	     *         a valid E.164 number
222	     */
223	    private String toE164(String telephone) {
224	        if (telephone == null) {
225	            return null;
226	        }
227	        String trimmed = telephone.trim();
228	        boolean hasCountryCode = trimmed.startsWith("+");
229	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
230	        if (hasCountryCode) {
231	            cleaned = cleaned.substring(1);
232	        }
233	        if (!cleaned.matches("[0-9]+")) {
234	            return null;
235	        }
236	        String digits;
237	        if (hasCountryCode) {
238	            digits = cleaned;
239	        } else {
240	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
241	            digits = "61" + national;
242	        }
243	        if (digits.length() < 8 || digits.length() > 15) {
244	            return null;
245	        }
246	        return "+" + digits;
247	    }
248	
249	    /**
250	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
251	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
252	     *
253	     * @param email the raw email value (must not be {@code null})
254	     * @return the trimmed, lower-cased email
255	     */
256	    private String normalizeEmail(String email) {
257	        return email.trim().toLowerCase(Locale.ROOT);
258	    }
259	
260	    /**
261	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
262	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
263	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
264	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
265	     * normalized form, and every household comparison uses it.
266	     *
267	     * @param address the raw address value (may be {@code null})
268	     * @return the normalized address, or {@code null} if the input was {@code null}
269	     */
270	    private String normalizeAddress(String address) {
271	        if (address == null) {
272	            return null;
273	        }
274	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
275	        if (collapsed.isEmpty()) {
276	            return collapsed;
277	        }
278	        String[] tokens = collapsed.split(" ");
279	        StringBuilder sb = new StringBuilder(collapsed.length());
280	        for (int i = 0; i < tokens.length; i++) {
281	            if (i > 0) {
282	                sb.append(' ');
283	            }
284	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
285	        }
286	        return sb.toString();
287	    }
288	
289	    /**
290	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
291	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
292	     * so that owners are compared case-insensitively with collapsed whitespace.
293	     *
294	     * @param value the raw value (must not be {@code null})
295	     * @return the normalized comparison key
296	     */
297	    private String householdKey(String value) {
298	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
299	    }
300	
301	    /**
302	     * Derives a stable, shared household identifier for the owner's household. The value is a
303	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
304	     * every owner in the same household derives the identical identifier of the form
305	     * {@code 'HH-<12 upper-case hex>'}.
306	     *
307	     * @param owner the owner whose household identifier is derived
308	     * @return the stable household identifier
309	     */
310	    private String householdId(Owner owner) {
311	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
312	        try {
313	            byte[] digest = MessageDigest.getInstance("SHA-256")
314	                .digest(key.getBytes(StandardCharsets.UTF_8));
315	            StringBuilder sb = new StringBuilder(digest.length * 2);
316	            for (byte b : digest) {
317	                sb.append(String.format("%02x", b));
318	            }
319	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
320	        }
321	        catch (java.security.NoSuchAlgorithmException e) {
322	            throw new IllegalStateException("SHA-256 not available", e);
323	        }
324	    }
325	
326	    /**
327	     * Builds the customer code for a newly registered owner in the form
328	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three
329	     * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
330	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
331	     * number of owners already registered in that city (e.g. {@code 'SYD-SMI-0007'}).
332	     *
333	     * @param city     the owner's city
334	     * @param lastName the owner's last name
335	     * @return the assigned customer code
336	     */
337	    private String nextCustomerCode(String city, String lastName) {
338	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
339	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
340	        String cityKey = householdKey(city);
341	        int sequence = (int) this.clinicService.findAllOwners().stream()
342	            .filter(existing -> existing.getCity() != null && cityKey.equals(householdKey(existing.getCity())))
343	            .count() + 1;
344	        return String.format(Locale.ROOT, "%s-%s-%04d", city3, last3, sequence);
345	    }
346	
347	    /**
348	     * Rolls a registration date forward onto a business day. When the given date falls on a
349	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
350	     *
351	     * @param date the effective registration date (must not be {@code null})
352	     * @return the same date if it is a weekday, otherwise the next Monday
353	     */
354	    private LocalDate toBusinessDay(LocalDate date) {
355	        DayOfWeek dayOfWeek = date.getDayOfWeek();
356	        if (dayOfWeek == DayOfWeek.SATURDAY) {
357	            return date.plusDays(2);
358	        }
359	        if (dayOfWeek == DayOfWeek.SUNDAY) {
360	            return date.plusDays(1);
361	        }
362	        return date;
363	    }
364	
365	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
366	    @Override
367	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
368	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
369	        if (currentOwner == null) {
370	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
371	        }
372	        String email = ownerFieldsDto.getEmail();
373	        if (email != null) {
374	            email = normalizeEmail(email);
375	            if (!EMAIL_PATTERN.matcher(email).matches()) {
376	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
377	            }
378	        }
379	        String telephone = toE164(ownerFieldsDto.getTelephone());
380	        if (telephone == null) {
381	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
382	        }
383	        currentOwner.setAddress(ownerFieldsDto.getAddress());
384	        currentOwner.setCity(ownerFieldsDto.getCity());
385	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
386	        currentOwner.setLastName(ownerFieldsDto.getLastName());
387	        currentOwner.setTelephone(telephone);
388	        currentOwner.setEmail(email);
389	        this.clinicService.saveOwner(currentOwner);
390	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
391	    }
392	
393	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
394	    @Transactional
395	    @Override
396	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
397	        Owner owner = this.clinicService.findOwnerById(ownerId);
398	        if (owner == null) {
399	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
400	        }
401	        this.clinicService.deleteOwner(owner);
402	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
403	    }
404	
405	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
406	    @Override
407	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
408	        Owner owner = this.clinicService.findOwnerById(ownerId);
409	        if (owner == null) {
410	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
411	        }
412	        HttpHeaders headers = new HttpHeaders();
413	        Pet pet = petMapper.toPet(petFieldsDto);
414	        owner.setId(ownerId);
415	        pet.setOwner(owner);
416	        pet.getType().setName(null);
417	        this.clinicService.savePet(pet);
418	        PetDto petDto = petMapper.toPetDto(pet);
419	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
420	            .buildAndExpand(pet.getId()).toUri());
421	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
422	    }
423	
424	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
425	    @Override
426	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
427	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
428	        if (currentOwner != null) {
429	            Pet currentPet = this.clinicService.findPetById(petId);
430	            if (currentPet != null) {
431	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
432	                currentPet.setName(petFieldsDto.getName());
433	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
434	                this.clinicService.savePet(currentPet);
435	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
436	            }
437	        }
438	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
439	    }
440	
441	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
442	    @Override
443	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
444	        HttpHeaders headers = new HttpHeaders();
445	        Visit visit = visitMapper.toVisit(visitFieldsDto);
446	        Pet pet = new Pet();
447	        pet.setId(petId);
448	        visit.setPet(pet);
449	        this.clinicService.saveVisit(visit);
450	        VisitDto visitDto = visitMapper.toVisitDto(visit);
451	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
452	            .buildAndExpand(visit.getId()).toUri());
453	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
454	    }
455	
456	
457	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
458	    @Override
459	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
460	        Owner owner = this.clinicService.findOwnerById(ownerId);
461	        if (owner != null) {
462	            Pet pet = owner.getPet(petId);
463	            if (pet != null) {
464	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
465	            }
466	        }
467	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
468	    }
469	}
