125	    public Integer getNamesakeCount() {
126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    /**
134	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
135	     *
136	     * @return the formatted display name
137	     */
138	    public String getDisplayName() {
139	        return this.getLastName() + ", " + this.getFirstName();
140	    }
141	
142	    /**
143	     * The owner's initials: the upper-cased first letters of the first and last
144	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
145	     *
146	     * @return the formatted initials
147	     */
148	    public String getInitials() {
149	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
150	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
151	    }
152	
153	    /**
154	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
155	     * {@code YY} is the last two digits of the registration date's year (e.g.
156	     * {@code "SYD-SMI-0007-M26"}).
157	     *
158	     * @return the formatted membership number, or {@code null} if the customer code or
159	     *         registration date has not been assigned
160	     */
161	    public String getMembershipNumber() {
162	        if (this.customerCode == null || this.registrationDate == null) {
163	            return null;
164	        }
165	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
166	    }
167	
168	    /**
169	     * The owner's membership tier: {@code "SILVER"} when this owner has no namesakes
170	     * ({@code namesakeCount} is {@code 0}) and carries an email address, otherwise
171	     * {@code "BRONZE"}.
172	     *
173	     * @return the membership tier
174	     */
175	    public String getMembershipTier() {
176	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
177	        boolean hasEmail = this.email != null && !this.email.isBlank();
178	        return (noNamesakes && hasEmail) ? "SILVER" : "BRONZE";
179	    }
180	
181	    /**
182	     * City -> canonical region, the fixed ground truth for deriving locality.
183	     */
184	    private static final Map<String, String> CITY_REGION = Map.of(
185	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
186	
187	    /**
188	     * The owner's locality: the canonical region derived from the city using the fixed
189	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
190	     * {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the city is not in the table.
191	     *
192	     * @return the canonical region string, or {@code "UNKNOWN"}
193	     */
194	    public String getLocality() {
195	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
196	    }
